// salary_assignments.js — generated by Generate Module

const { createApp } = Vue;

function emptyDetailLine() {
  return { salary_component_ref: '', salary_component_name: '', value: 0 };
}

createApp({
  data() {
    return {
      systemName: SYSTEM_NAME,
      title:      '',
      loading: false,
      saving:  false,
      saved:   false,
      error:   '',
      isEditing: false,
      detailPickerIndex: null,
      form: {
        ref: '',
      employment_record_ref: '',
      employment_record_name: '',
      currency_ref: '',
      currency_name: '',
      effective_from: '',
      effective_to: '',
      remarks: '',
      details: [emptyDetailLine()],
      },
    };
  },

  computed: {
    isDirty() {
      return (
        this.form.employment_record_ref !== '' ||
        this.form.currency_ref !== '' ||
        this.form.effective_from !== '' ||
        this.form.effective_to !== '' ||
        this.form.remarks !== '' ||
        this.form.details.some(l => l.salary_component_ref !== '' || (parseFloat(l.value) || 0) !== 0)
      );
    },
  },

  mounted() {
    this.fetchRefNumber();
    document.addEventListener('salary_assignments-selected', (e) => this.loadRecord(e.detail));
    document.addEventListener('sa-employment-record-selected', (e) => {
      this.form.employment_record_ref  = e.detail.ref;
      this.form.employment_record_name = e.detail.m_employees?.full_name ?? e.detail.ref;
    });
    document.addEventListener('sa-currency-selected', (e) => {
      this.form.currency_ref  = e.detail.ref;
      this.form.currency_name = e.detail.currency_name;
    });
    document.addEventListener('sa-component-selected', (e) => {
      const line = this.form.details[this.detailPickerIndex];
      if (!line) return;
      line.salary_component_ref  = e.detail.ref;
      line.salary_component_name = e.detail.name;
    });
  },

  methods: {
    fetchRefNumber() {
      this.loading = true;
      axios.get('/server/general/module_data.php?system_name=' + this.systemName)
        .then(res => { this.form.ref = res.data.ref; this.title = res.data.module; })
        .catch(err => { this.error = 'Failed to load reference number.'; console.error(err); })
        .finally(() => { this.loading = false; });
    },

    clearEmploymentRecord() { this.form.employment_record_ref = ''; this.form.employment_record_name = ''; },
    clearCurrency()         { this.form.currency_ref = '';          this.form.currency_name = ''; },

    openComponentPicker(i) { this.detailPickerIndex = i; },
    addDetailLine()        { this.form.details.push(emptyDetailLine()); },
    removeDetailLine(i)    { if (this.form.details.length > 1) this.form.details.splice(i, 1); },

    onAdd()    { this.onReset(); this.fetchRefNumber(); },
    onPrint() {
      if (!this.form.ref) { this.error = 'No record to print. Search and select a saved record first.'; return; }
      axios.get('/modules/human_resources_payroll/salary_setup/salary_assignments/salary_assignments_data.php?action=exists&ref=' + encodeURIComponent(this.form.ref))
        .then(res => {
          if (!res.data.exists) {
            this.error = 'No saved record found for this reference. Please search and select a record to print.';
            return;
          }
          const params = new URLSearchParams({
            ref: this.form.ref,
        employment_record_name: String(this.form.employment_record_name ?? ''),
        currency_name: String(this.form.currency_name ?? ''),
        effective_from: String(this.form.effective_from ?? ''),
        effective_to: String(this.form.effective_to ?? ''),
        remarks: String(this.form.remarks ?? ''),
        details: JSON.stringify(this.form.details.filter(l => l.salary_component_ref !== '')),
          });
          window.open('/modules/human_resources_payroll/salary_setup/salary_assignments/salary_assignments_print.php?' + params.toString(), '_blank');
        })
        .catch(err => { this.error = 'Failed to verify record.'; console.error(err); });
    },
    onCancel() { this.onReset(); },
    onClose()  { this.onReset(); },

    onReset() {
      this.saved = false;
      this.error = '';
      this.isEditing = false;
      this.form.employment_record_ref = '';
      this.form.employment_record_name = '';
      this.form.currency_ref = '';
      this.form.currency_name = '';
      this.form.effective_from = '';
      this.form.effective_to = '';
      this.form.remarks = '';
      this.form.details = [emptyDetailLine()];
    },

    onSave() {
      if (!this.isDirty) return;
      const details = this.form.details.filter(l => l.salary_component_ref !== '');
      if (!details.length) { this.error = 'Add at least one salary component line.'; return; }
      this.saving = true;
      this.saved  = false;
      this.error  = '';
      const action = this.isEditing ? 'update' : 'save';
      axios.post('/modules/human_resources_payroll/salary_setup/salary_assignments/salary_assignments_data.php?action=' + action, { ...this.form, details })
        .then(() => {
          this.saved = true;
          this.onReset();
          this.fetchRefNumber();
        })
        .catch(err => { this.error = 'Failed to save.'; console.error(err); })
        .finally(() => { this.saving = false; });
    },

    loadRecord(data) {
      this.isEditing = true;
      this.form.ref = data.ref;
      this.form.employment_record_ref = data.employment_record_ref ?? '';
      this.form.employment_record_name = data.m_employment_records?.m_employees?.full_name ?? data.employment_record_ref ?? '';
      this.form.currency_ref = data.currency_ref ?? '';
      this.form.currency_name = data.m_currencies?.currency_name ?? '';
      this.form.effective_from = data.effective_from;
      this.form.effective_to = data.effective_to;
      this.form.remarks = data.remarks;
      const details = data.m_salary_assignment_details ?? [];
      this.form.details = details.length
        ? details.map(d => ({
            salary_component_ref:  d.salary_component_ref ?? '',
            salary_component_name: d.m_salary_components?.name ?? '',
            value: d.value,
          }))
        : [emptyDetailLine()];
      this.saved = false;
      this.error = '';
    },
  },
}).mount('#salary-assignments-app');